                sys.exit(4)

        values[key] = value

    if "name" not in values:
        print("missing key: name")
        sys.exit(5)
    if "port" not in values:
        print("missing key: port")
        sys.exit(5)

    os.makedirs("out", exist_ok=True)
    out_text = "".join(f"{k}={values[k]}\n" for k in sorted(values))
